"""Write-provenance for memory writes in the runtime.

Cross-phase corrections need to answer two questions about any value the
assistant has stored:

1. **Who produced it?** — so a correction can re-invoke the same producer
   (a builder tool) with a changed argument, or simply re-set a collect-owned
   field.
2. **When was it written, relative to other writes?** — so a rewind can clear
   exactly the values written *after* the point the conversation jumps back to.

Both are answered by stamping a small provenance record into every
:class:`~rasa.shared.core.events.SlotSet` / ``MemorySet`` /
``MemoryCleared`` ``metadata`` under
:data:`PROVENANCE_METADATA_KEY`. The record is persisted with the event, so it
survives serialization and tracker replay without any extra bookkeeping.

The provenance is intentionally engine-internal: it records the *producing
context* (tool, step, frame, arguments, position), never user data beyond the
tool arguments the assistant already chose. Reads are tolerant — a missing or
malformed record simply yields ``None`` so older trackers (written before this
feature) keep working.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, Iterator, Optional, Tuple

from pydantic import BaseModel, ConfigDict, Field

from rasa.shared.core.events import (
    Event,
    MemoryCleared,
    MemorySet,
    SlotSet,
    is_memory_write_event,
)

# Key under memory-write event metadata where the provenance record is stored.
# Namespaced to avoid colliding with any other metadata a write may carry.
PROVENANCE_METADATA_KEY = "mantle_write_provenance"


class WriteProvenance(BaseModel):
    """Records the producing context of a single memory write.

    Attributes:
        tool: Name of the builder tool that produced the value, or ``None``
            for engine-internal writes (collect setters, ``set_memory`` steps).
            A non-``None`` ``tool`` is the signal that a correction can
            re-invoke a producer rather than just re-setting the slot.
        skill_id: Id of the skill whose scope was active when the write
            happened, or ``None`` when no skill scope was resolvable (a write
            made while routing). Lets the inspector attribute a write to its
            owning skill without re-deriving it from the slot name.
        step: Id of the flow step active when the write happened.
        frame_id: Id of the stack frame active when the write happened.
        arguments: The arguments the producing builder tool was called with,
            captured via ``TrackerHandle.recording_write`` around the tool
            dispatch (used to re-invoke the producer on a correction). Empty
            (``{}``) for engine-internal writes — collect setters and
            ``set_memory`` steps run without a recording context, so their value
            is read from the slot rather than reconstructed from here.
        position: Monotonic ordinal of the write within the conversation,
            aligned with tracker event order. Used to compare "written before
            vs. after" a rewind point.
        tool_call_id: Id of the LLM tool call whose dispatch produced the
            write, captured via ``TrackerHandle.recording_tool_call`` around
            ``dispatch_tool_call``. This is the exact join key to the
            ``ToolExecuted`` event's ``tool_call_id`` metadata, letting
            consumers (e.g. the Inspector) attribute a write to its tool-call
            row without ordering heuristics. ``None`` for engine-invoked
            writes (deterministic execute steps, replay) and for records
            written before this field existed.
    """

    model_config = ConfigDict(frozen=True)

    tool: Optional[str] = None
    skill_id: Optional[str] = None
    step: Optional[str] = None
    frame_id: Optional[str] = None
    arguments: Dict[str, Any] = Field(default_factory=dict)
    position: int = 0
    tool_call_id: Optional[str] = None

    def as_metadata(self) -> Dict[str, Any]:
        """Return the JSON-serializable dict stored under the metadata key."""
        return {
            "tool": self.tool,
            "skill_id": self.skill_id,
            "step": self.step,
            "frame_id": self.frame_id,
            "arguments": dict(self.arguments),
            "position": self.position,
            "tool_call_id": self.tool_call_id,
        }

    @classmethod
    def from_metadata(cls, data: Any) -> Optional["WriteProvenance"]:
        """Rebuild a :class:`WriteProvenance` from stored metadata, if valid.

        Returns ``None`` for anything that is not a well-formed provenance
        record so callers can treat legacy / unstamped writes uniformly.
        """
        if not isinstance(data, dict):
            return None
        arguments = data.get("arguments")
        if not isinstance(arguments, dict):
            arguments = {}
        try:
            position = int(data.get("position", 0))
        except (TypeError, ValueError):
            position = 0
        tool_call_id = data.get("tool_call_id")
        if not isinstance(tool_call_id, str):
            tool_call_id = None
        return cls(
            tool=data.get("tool"),
            skill_id=data.get("skill_id"),
            step=data.get("step"),
            frame_id=data.get("frame_id"),
            arguments=dict(arguments),
            position=position,
            tool_call_id=tool_call_id,
        )

    @property
    def produced_by_tool(self) -> bool:
        """``True`` when a builder tool produced the value (re-invokable)."""
        return bool(self.tool)


def attach_provenance(event: Event, provenance: WriteProvenance) -> None:
    """Stamp *provenance* onto *event*'s metadata in place.

    No-op if the event already carries provenance — the first writer wins, so
    explicitly-stamped writes (e.g. a correction re-applying a value) are never
    clobbered by the generic stamping path.
    """
    if not is_memory_write_event(event):
        return
    if read_provenance(event) is not None:
        return
    metadata = dict(event.metadata or {})
    metadata[PROVENANCE_METADATA_KEY] = provenance.as_metadata()
    event.metadata = metadata


def read_provenance(event: Event) -> Optional[WriteProvenance]:
    """Return the :class:`WriteProvenance` stamped on *event*, or ``None``."""
    metadata = getattr(event, "metadata", None)
    if not metadata:
        return None
    return WriteProvenance.from_metadata(metadata.get(PROVENANCE_METADATA_KEY))


def iter_slot_writes(
    events: Iterable[Event],
) -> Iterator[Tuple[SlotSet | MemorySet | MemoryCleared, Optional[WriteProvenance]]]:
    """Yield each memory write in *events* paired with its read provenance.

    This is the single primitive behind every provenance scan: "walk the event
    log and read each write's provenance" is the one loop all callers share,
    whether they want the latest write to one slot, a specific frame's write, or
    a full per-slot map (:func:`~rasa.mantle.orchestration.correction.discovery`).
    Centralizing it keeps one definition of "a provenanced memory write" instead of
    several near-identical loops.
    """
    for event in events:
        if is_memory_write_event(event):
            yield event, read_provenance(event)


def latest_provenance_for_slot(
    events: Iterable[Event], slot_name: str
) -> Optional[WriteProvenance]:
    """Return the provenance of the most recent stamped write to *slot_name*.

    Scans *events* in order and keeps the last memory write for the slot
    that carries provenance. Returns ``None`` when the slot was never written
    with provenance (e.g. set before this feature shipped).
    """
    latest: Optional[WriteProvenance] = None
    for event, provenance in iter_slot_writes(events):
        if event.key == slot_name and provenance is not None:
            latest = provenance
    return latest


def provenance_for_slot_by_frame(
    events: Iterable[Event], slot_name: str, frame_id: str
) -> Optional[WriteProvenance]:
    """Return the *earliest* stamped write to *slot_name* by *frame_id*.

    Used for cross-skill re-entry: a value's original production by the (now
    completed) sub-skill frame is the correct anchor and re-invokable producer,
    even if a still-live ancestor later re-stamped the same slot at a higher
    position. Returns ``None`` when that frame never wrote the slot with
    provenance.
    """
    for event, provenance in iter_slot_writes(events):
        if (
            event.key == slot_name
            and provenance is not None
            and provenance.frame_id == frame_id
        ):
            return provenance
    return None
